<?php
use GhoroaHat\Rewards\{DB,Settings,Membership,Wallet,Orders,Reconciliation,Notifications};
add_filter('pre_wp_mail','__return_true');global $wpdb,$ghr_reconcile_count;$ghr_reconcile_count=0;$old=Settings::all();$run='identity'.bin2hex(random_bytes(5));
function reconcile_check($a,$b,$message){global $ghr_reconcile_count;++$ghr_reconcile_count;if($a!==$b){throw new RuntimeException($message.': '.var_export($a,true).' != '.var_export($b,true));}echo "PASS $message\n";}
function reconcile_fixture($name){$u=wp_insert_user(array('user_login'=>$name,'user_email'=>$name.'@example.org','user_pass'=>wp_generate_password()));Membership::enroll($u);DB::update(DB::table('memberships'),array('email_verified_at'=>DB::now()),array('user_id'=>$u));return $u;}
try{
$p=new WC_Product_Simple();$p->set_name('Identity package');$p->set_regular_price('999');$p->set_tax_status('none');$p->save();Settings::save(array('bonus_products'=>array($p->get_id()),'excluded_products'=>array(),'excluded_categories'=>array()));
$source=reconcile_fixture($run.'source');$target=reconcile_fixture($run.'target');$source_member_id=Membership::get($source)['member_id'];$orders=array();foreach(array($source,$target)as$u){$o=wc_create_order(array('customer_id'=>$u));$o->add_product($p,1);$o->set_billing_email(get_userdata($u)->user_email);$o->calculate_totals();$o->update_status('completed');Orders::reconcile($o->get_id());$orders[]=$o;}
// A historical accepted COD redemption belongs to the source before reconciliation.
$redemption=wc_create_order(array('customer_id'=>$source));$redemption->add_product($p,2);$redemption->calculate_totals();$redemption->set_payment_method('cod');$redemption->update_status('processing');$r=Wallet::reserve($source,'trust',6000,$run.'-old-redemption',hash('sha256','cart'));Wallet::bind($r['id'],$source,$redemption->get_id());Wallet::commit($r['id'],$source,$redemption->get_id());$redemption->update_meta_data('_ghr_reservation',$r['id']);$redemption->update_meta_data('_ghr_credit_units',6000);$redemption->update_meta_data('_ghr_credit_wallet','trust');$redemption->save();
Notifications::emit($source,$run.'source-notice','announcement');$preview=Reconciliation::preview($source,$target,'Verified duplicate identity evidence');Reconciliation::execute($preview['case_id'],$preview['confirmation']);
reconcile_check(Membership::get($source)['status'],'closed','Source membership closes without deleting user');reconcile_check(Membership::canonical($source),$target,'Permanent canonical user mapping retained');reconcile_check(Membership::get($source)['member_id'],$source_member_id,'Original public member ID remains an alias');reconcile_check(Wallet::account($source,'trust')['posted'],0,'Source trust account balanced to zero');reconcile_check(Wallet::account($target,'trust')['posted'],4000,'Duplicate introductory bonus reversed including already-spent value');reconcile_check(Wallet::account($target,'seeds')['posted'],18,'Personal Seeds consolidate separately');reconcile_check((int)wc_get_order($orders[0]->get_id())->get_customer_id(),$source,'Original WooCommerce customer/order identity untouched');reconcile_check((int)Wallet::reservation($r['id'])['user_id'],$target,'Historical redemption obligation follows canonical member');
wp_set_current_user($target);reconcile_check(current_user_can('view_order',$orders[0]->get_id()),true,'Canonical owner can view legitimate historical WooCommerce order');$query=apply_filters('woocommerce_my_account_my_orders_query',array('customer'=>$target,'limit'=>100,'return'=>'ids'));reconcile_check(in_array($orders[0]->get_id(),wc_get_orders($query)),true,'Native My Account order list includes approved alias orders');reconcile_check(count(Wallet::history($target))>3,true,'Canonical ledger view includes immutable source history');
$redemption->update_status('cancelled');Orders::reconcile($redemption->get_id());reconcile_check(Wallet::account($target,'trust')['posted'],10000,'Cancelled historical redemption restores canonical credit');$a=Wallet::account($target,'trust');reconcile_check((int)$wpdb->get_var($wpdb->prepare('SELECT SUM(remaining) FROM '.DB::table('credit_lots').' WHERE account_id=%d',$a['id'])),10000,'Restoration recovers the credits that covered migrated debt');
$orders[0]->update_status('cancelled');Orders::reconcile($orders[0]->get_id());reconcile_check(Wallet::account($target,'seeds')['posted'],9,'Later source-order reversal posts to canonical wallet');reconcile_check(Wallet::account($target,'trust')['posted'],10000,'Source bonus cannot be reversed twice after deduplication');reconcile_check((int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('wallet_accounts').' a WHERE posted<>(SELECT COALESCE(SUM(amount),0) FROM '.DB::table('wallet_transactions').' t WHERE t.account_id=a.id)'),0,'All original and canonical ledger projections reconcile');
echo "RECONCILIATION PASS: $ghr_reconcile_count assertions\n";
}finally{update_option('ghr_settings',$old,false);}
